/**
 * Fetch events from Kulturhuset Elasticsearch API
 * @param {Object} options - Options (limit, page, fetchAll)
 * @param {number} options.limit - Max events per page (default 100)
 * @param {number} options.page - Page number (default 0)
 * @param {boolean} options.fetchAll - Fetch all pages until no more events (default false)
 * @returns {Promise<Object[]>} - Array of events
 */
export async function fetchKulturhusetEvents(options = {}) {
  const { limit = 100, page = 0, fetchAll = false } = options;

  if (fetchAll) {
    // Fetch all events using pagination
    const allEvents: ReturnType<typeof mapKulturhusetEvent>[] = [];
    let currentPage = 0;
    let hasMore = true;

    while (hasMore) {
      const pageEvents = await fetchPage(currentPage, limit);
      if (pageEvents.length === 0) {
        hasMore = false;
      } else {
        allEvents.push(...pageEvents);
        currentPage++;
        // Safety limit to prevent infinite loops
        if (currentPage >= 100) {
          console.log('[kulturhuset] Reached max pages (100), stopping');
          break;
        }
      }
    }

    console.log(`[kulturhuset] Fetched ${allEvents.length} total events across ${currentPage} pages`);
    return allEvents;
  }

  return fetchPage(page, limit);
}

